(* [comment removed for export] *)
Fixpoint ivls_client (live : list (Z * Z)) (frames : list (Z * nat)) (sp : Z) (W : list (Z * Z)) : Prop :=
  match W with
  | [] => True
  | (lo, hi) :: W' => (forall x, lo <= x < hi -> aclient live frames sp x) /\ ivls_client live frames sp W'
  end.

